CREATE TABLE IF NOT EXISTS operaciones.preparaciones(tenant_id uuid NOT NULL,empresa_id uuid NOT NULL,pedido_id uuid NOT NULL,nodo_id uuid NOT NULL,estado text NOT NULL DEFAULT 'IN_PROGRESS' CHECK(estado IN('IN_PROGRESS','COMPLETED','CANCELLED')),iniciado_por uuid NOT NULL REFERENCES plataforma.users(id),iniciado_en timestamptz NOT NULL DEFAULT transaction_timestamp(),completado_en timestamptz,version bigint NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,empresa_id,pedido_id),FOREIGN KEY(tenant_id,empresa_id,pedido_id) REFERENCES operaciones.pedidos(tenant_id,empresa_id,id),FOREIGN KEY(tenant_id,empresa_id,nodo_id) REFERENCES operaciones.nodos(tenant_id,empresa_id,id));
CREATE TABLE IF NOT EXISTS operaciones.preparacion_lineas(tenant_id uuid NOT NULL,empresa_id uuid NOT NULL,pedido_id uuid NOT NULL,linea_id uuid NOT NULL,estado text NOT NULL DEFAULT 'PENDING' CHECK(estado IN('PENDING','DONE')),motivo text,actualizado_por uuid REFERENCES plataforma.users(id),actualizado_en timestamptz NOT NULL DEFAULT transaction_timestamp(),version bigint NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,empresa_id,pedido_id,linea_id),FOREIGN KEY(tenant_id,empresa_id,pedido_id) REFERENCES operaciones.preparaciones(tenant_id,empresa_id,pedido_id),FOREIGN KEY(linea_id) REFERENCES operaciones.pedido_lineas(id));
ALTER TABLE operaciones.preparaciones ENABLE ROW LEVEL SECURITY;ALTER TABLE operaciones.preparacion_lineas ENABLE ROW LEVEL SECURITY;REVOKE ALL ON operaciones.preparaciones,operaciones.preparacion_lineas FROM PUBLIC,mastererp_app;
INSERT INTO plataforma.permissions(code,description) VALUES('operations.preparation.read','Read order preparation'),('operations.preparation.write','Start and complete order preparation') ON CONFLICT(code) DO NOTHING;
CREATE OR REPLACE FUNCTION operaciones.preparacion_leer(p_empresa uuid,p_pedido uuid DEFAULT NULL,p_estado text DEFAULT NULL,p_limit integer DEFAULT 50) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operaciones,plataforma,pg_temp AS $$ DECLARE result jsonb;BEGIN IF p_limit NOT BETWEEN 1 AND 101 THEN RAISE EXCEPTION 'Invalid input' USING ERRCODE='22023';END IF;IF plataforma.has_current_tenant_capability('erp.operations','operations.preparation.read',p_empresa) IS NOT TRUE THEN RAISE EXCEPTION 'Preparation access denied' USING ERRCODE='42501';END IF;SELECT COALESCE(jsonb_agg(item ORDER BY iniciado_en,pedido_id),'[]')INTO result FROM(SELECT p.iniciado_en,p.pedido_id,jsonb_build_object('order_id',p.pedido_id,'node_id',p.nodo_id,'status',p.estado,'version',p.version,'started_at',p.iniciado_en,'completed_at',p.completado_en,'items',(SELECT COALESCE(jsonb_agg(jsonb_build_object('line_id',l.linea_id,'status',l.estado,'reason',l.motivo,'version',l.version)ORDER BY ol.posicion),'[]')FROM operaciones.preparacion_lineas l JOIN operaciones.pedido_lineas ol ON ol.id=l.linea_id WHERE(l.tenant_id,l.empresa_id,l.pedido_id)=(p.tenant_id,p.empresa_id,p.pedido_id)))item FROM operaciones.preparaciones p WHERE p.tenant_id=plataforma.current_app_tenant_id()AND p.empresa_id=p_empresa AND(p_pedido IS NULL OR p.pedido_id=p_pedido)AND(p_estado IS NULL OR p.estado=p_estado)LIMIT p_limit)q;IF p_pedido IS NOT NULL AND jsonb_array_length(result)=0 THEN RAISE EXCEPTION 'Preparation not found' USING ERRCODE='P0002';END IF;RETURN CASE WHEN p_pedido IS NULL THEN result ELSE result->0 END;END $$;
CREATE OR REPLACE FUNCTION operaciones.preparacion_iniciar(p_empresa uuid,p_pedido uuid,p_nodo uuid,p_version bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operaciones,plataforma,auditoria,pg_temp AS $$ DECLARE tenant uuid:=plataforma.current_app_tenant_id();actor uuid:=plataforma.current_app_user_id();current operaciones.pedidos%ROWTYPE;corr uuid;BEGIN IF plataforma.has_current_tenant_capability('erp.operations','operations.preparation.write',p_empresa,p_nodo) IS NOT TRUE OR NULLIF(current_setting('app.current_operation',true),'') IS DISTINCT FROM 'operations.preparation.start' THEN RAISE EXCEPTION 'Preparation start denied' USING ERRCODE='42501';END IF;SELECT * INTO current FROM operaciones.pedidos WHERE tenant_id=tenant AND empresa_id=p_empresa AND id=p_pedido FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Order not found' USING ERRCODE='P0002';END IF;IF current.version<>p_version THEN RAISE EXCEPTION 'Stale order version' USING ERRCODE='40001';END IF;IF current.estado<>'CONFIRMED' THEN RAISE EXCEPTION 'Order not confirmed' USING ERRCODE='23514';END IF;INSERT INTO operaciones.preparaciones VALUES(tenant,p_empresa,p_pedido,p_nodo,'IN_PROGRESS',actor,transaction_timestamp(),NULL,1);INSERT INTO operaciones.preparacion_lineas(tenant_id,empresa_id,pedido_id,linea_id)SELECT tenant,p_empresa,p_pedido,id FROM operaciones.pedido_lineas WHERE tenant_id=tenant AND empresa_id=p_empresa AND pedido_id=p_pedido;UPDATE operaciones.pedidos SET estado='PREPARING',version=version+1,actualizado_en=transaction_timestamp()WHERE id=p_pedido;corr:=NULLIF(current_setting('app.correlation_id',true),'')::uuid;INSERT INTO operaciones.pedido_eventos(tenant_id,empresa_id,pedido_id,estado_anterior,estado_nuevo,motivo,actor_id,correlation_id)VALUES(tenant,p_empresa,p_pedido,'CONFIRMED','PREPARING','PREPARATION_STARTED',actor,corr);RETURN operaciones.preparacion_leer(p_empresa,p_pedido);END $$;
CREATE OR REPLACE FUNCTION operaciones.preparacion_linea_marcar(p_empresa uuid,p_pedido uuid,p_linea uuid,p_version bigint,p_estado text,p_motivo text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operaciones,plataforma,pg_temp AS $$ DECLARE tenant uuid:=plataforma.current_app_tenant_id();actor uuid:=plataforma.current_app_user_id();prep operaciones.preparaciones%ROWTYPE;line operaciones.preparacion_lineas%ROWTYPE;BEGIN SELECT * INTO prep FROM operaciones.preparaciones WHERE tenant_id=tenant AND empresa_id=p_empresa AND pedido_id=p_pedido FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Preparation not found' USING ERRCODE='P0002';END IF;IF plataforma.has_current_tenant_capability('erp.operations','operations.preparation.write',p_empresa,prep.nodo_id) IS NOT TRUE OR NULLIF(current_setting('app.current_operation',true),'') IS DISTINCT FROM 'operations.preparation.item.update' THEN RAISE EXCEPTION 'Preparation update denied' USING ERRCODE='42501';END IF;IF prep.estado<>'IN_PROGRESS' OR p_estado NOT IN('PENDING','DONE') THEN RAISE EXCEPTION 'Invalid preparation state' USING ERRCODE='23514';END IF;SELECT * INTO line FROM operaciones.preparacion_lineas WHERE tenant_id=tenant AND empresa_id=p_empresa AND pedido_id=p_pedido AND linea_id=p_linea FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Preparation item not found' USING ERRCODE='P0002';END IF;IF line.version<>p_version THEN RAISE EXCEPTION 'Stale item version' USING ERRCODE='40001';END IF;IF p_estado='PENDING'AND length(btrim(COALESCE(p_motivo,'')))=0 THEN RAISE EXCEPTION 'Reason required' USING ERRCODE='22023';END IF;UPDATE operaciones.preparacion_lineas SET estado=p_estado,motivo=NULLIF(btrim(p_motivo),''),actualizado_por=actor,actualizado_en=transaction_timestamp(),version=version+1 WHERE tenant_id=tenant AND empresa_id=p_empresa AND pedido_id=p_pedido AND linea_id=p_linea;UPDATE operaciones.preparaciones SET version=version+1 WHERE tenant_id=tenant AND empresa_id=p_empresa AND pedido_id=p_pedido;RETURN operaciones.preparacion_leer(p_empresa,p_pedido);END $$;
CREATE OR REPLACE FUNCTION operaciones.preparacion_completar(p_empresa uuid,p_pedido uuid,p_version bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operaciones,catalogo,plataforma,pg_temp AS $$ DECLARE tenant uuid:=plataforma.current_app_tenant_id();actor uuid:=plataforma.current_app_user_id();prep operaciones.preparaciones%ROWTYPE;ord operaciones.pedidos%ROWTYPE;corr uuid;reservation uuid;BEGIN SELECT * INTO prep FROM operaciones.preparaciones WHERE tenant_id=tenant AND empresa_id=p_empresa AND pedido_id=p_pedido FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Preparation not found' USING ERRCODE='P0002';END IF;IF plataforma.has_current_tenant_capability('erp.operations','operations.preparation.write',p_empresa,prep.nodo_id) IS NOT TRUE OR NULLIF(current_setting('app.current_operation',true),'') IS DISTINCT FROM 'operations.preparation.complete' THEN RAISE EXCEPTION 'Preparation completion denied' USING ERRCODE='42501';END IF;IF prep.version<>p_version THEN RAISE EXCEPTION 'Stale preparation version' USING ERRCODE='40001';END IF;IF EXISTS(SELECT 1 FROM operaciones.preparacion_lineas WHERE tenant_id=tenant AND empresa_id=p_empresa AND pedido_id=p_pedido AND estado<>'DONE')THEN RAISE EXCEPTION 'Items pending' USING ERRCODE='23514';END IF;SELECT * INTO ord FROM operaciones.pedidos WHERE tenant_id=tenant AND empresa_id=p_empresa AND id=p_pedido FOR UPDATE;IF ord.estado<>'PREPARING' THEN RAISE EXCEPTION 'Order not preparing' USING ERRCODE='23514';END IF;reservation:=ord.reserva_inventario_ref::uuid;PERFORM set_config('app.current_operation','catalog.inventory.reservation.finalize',true);PERFORM catalogo.inventario_reserva_finalizar(p_empresa,reservation,'COMMIT','PREPARATION_COMPLETED');PERFORM set_config('app.current_operation','operations.preparation.complete',true);UPDATE operaciones.preparaciones SET estado='COMPLETED',completado_en=transaction_timestamp(),version=version+1 WHERE tenant_id=tenant AND empresa_id=p_empresa AND pedido_id=p_pedido;UPDATE operaciones.pedidos SET estado='READY',version=version+1,actualizado_en=transaction_timestamp()WHERE id=p_pedido;corr:=NULLIF(current_setting('app.correlation_id',true),'')::uuid;INSERT INTO operaciones.pedido_eventos(tenant_id,empresa_id,pedido_id,estado_anterior,estado_nuevo,motivo,actor_id,correlation_id)VALUES(tenant,p_empresa,p_pedido,'PREPARING','READY','PREPARATION_COMPLETED',actor,corr);RETURN operaciones.preparacion_leer(p_empresa,p_pedido);END $$;
REVOKE ALL ON FUNCTION operaciones.preparacion_leer(uuid,uuid,text,integer),operaciones.preparacion_iniciar(uuid,uuid,uuid,bigint),operaciones.preparacion_linea_marcar(uuid,uuid,uuid,bigint,text,text),operaciones.preparacion_completar(uuid,uuid,bigint) FROM PUBLIC;GRANT EXECUTE ON FUNCTION operaciones.preparacion_leer(uuid,uuid,text,integer),operaciones.preparacion_iniciar(uuid,uuid,uuid,bigint),operaciones.preparacion_linea_marcar(uuid,uuid,uuid,bigint,text,text),operaciones.preparacion_completar(uuid,uuid,bigint) TO mastererp_app;
